import type { DrawRect } from './geometry.js'
import type {
  TreemapDataPoint,
  TreemapDisplayMode,
  TreemapOthers,
  TreemapValueScale,
} from './types.js'

import { isObject, toFont, valueOrDefault } from 'chart.js/helpers'

import { parseBorderWidth } from './options.js'
import { packInto, sortNodes, toNodes, WEIGHT_KEY } from './squarify.js'
import { getCaptionHeight, shouldDrawCaption } from './text/index.js'
import { getGroupKey, group, normalizeTreeToArray } from './utils.js'

export type LayoutOptions = {
  borderWidth: any
  captions: any
  displayMode: TreemapDisplayMode
  groups: any[]
  leafKey: string
  others: false | TreemapOthers
  spacing: number
  unsorted: boolean
  valueScale: TreemapValueScale
}

/** A node while the layout is being built; `_children` is dropped before use. */
export type LayoutNode = TreemapDataPoint & { _children?: LayoutNode[] }

/**
 * Pass one: the hierarchy.
 *
 * Groups the items level by level and orders each set of siblings. Nothing here
 * depends on the chart area, so the number of nodes and their order are known
 * before the layout has a rectangle to fill.
 */
function buildHierarchy(
  values: any[],
  gidx: number,
  keys: string[],
  layout: LayoutOptions,
  weighted: boolean,
  parentGroupValue?: string
): LayoutNode[] {
  const { groups, leafKey, unsorted } = layout
  const glen = groups.length
  const g = getGroupKey(groups[gidx])
  const gdata = group(
    values,
    g,
    keys,
    leafKey,
    undefined,
    parentGroupValue,
    groups.filter((_item: any, index: number) => index <= gidx),
    groups,
    gidx
  )
  const nodes = toNodes(gdata, keys, g, gidx) as LayoutNode[]

  for (const node of nodes) {
    const record = node._data as any
    const nextGroupIndex = record.groupIndex + 1
    const children =
      gidx < glen - 1 && nextGroupIndex < glen
        ? buildHierarchy(record.children, nextGroupIndex, keys, layout, weighted, node.g)
        : []
    // Non-enumerable: the geometry pass needs it on every layout, but it
    // must not show up in ctx.raw.
    Object.defineProperty(node, '_children', {
      configurable: true,
      value: children,
      writable: true,
    })
    node.isLeaf = !children.length
  }

  // Weights depend on the children, so they are set before the siblings are
  // ordered: a scaled group can rank differently from a raw one.
  if (weighted) {
    applyValueScale(nodes, scaleFor(layout))
  }
  const withOthers = layout.others ? applyOthers(nodes, layout.others, weighted) : nodes
  if (!unsorted) {
    sortNodes(withOthers, weighted)
  }
  return withOthers
}

/**
 * The layout weight of every node, when `valueScale` is not linear.
 *
 * A leaf's weight is its scaled value; a group's is the sum of its children's,
 * so a group still covers exactly the area its contents do. `v` is untouched:
 * tooltips, labels and `sumKeys` stay in the units the data came in.
 */
function applyValueScale(nodes: LayoutNode[], scale: (value: number, item: any) => number) {
  for (const node of nodes) {
    const children = node._children
    let weight: number
    if (children?.length) {
      applyValueScale(children, scale)
      weight = children.reduce((total, child) => total + (child as any)[WEIGHT_KEY], 0)
    } else {
      const scaled = scale(node.v, node._data)
      weight = Number.isFinite(scaled) && scaled > 0 ? scaled : 0
    }
    Object.defineProperty(node, WEIGHT_KEY, { configurable: true, value: weight, writable: true })
  }
}

/**
 * Replaces the leaves too small to see with one tile that stands for all of
 * them.
 *
 * The question behind #213 is "where did my small items go", and a compressed
 * scale answers it by distorting the areas. This answers it by admitting the
 * items are too small and naming them instead. Groups are never bucketed: a
 * group is already a summary.
 */
function applyOthers(nodes: LayoutNode[], others: TreemapOthers, weighted: boolean) {
  const { label = 'Other', minCount = 2, threshold } = others
  // A node with children is a group, and a group is already a summary.
  if (!(threshold > 0) || nodes.some((node) => node._children?.length)) {
    return nodes
  }

  const weightOf = (node: LayoutNode) => (weighted ? (node as any)[WEIGHT_KEY] : node.v)
  const total = nodes.reduce((sum, node) => sum + weightOf(node), 0)
  if (!(total > 0)) {
    return nodes
  }

  const small = nodes.filter((node) => weightOf(node) / total < threshold)
  if (small.length < Math.max(2, minCount)) {
    return nodes
  }

  const kept = nodes.filter((node) => !small.includes(node))
  const bucket: LayoutNode = {
    _data: { label, others: small.map((node) => node._data) },
    h: 0,
    isLeaf: true,
    isOthers: true,
    s: 0,
    v: small.reduce((sum, node) => sum + node.v, 0),
    vs: sumValues(small),
    w: 0,
    x: 0,
    y: 0,
  }
  const grouped = nodes.find((node) => node.g !== undefined)
  if (grouped) {
    bucket.g = label
    bucket.l = grouped.l
  }
  if (weighted) {
    Object.defineProperty(bucket, WEIGHT_KEY, {
      configurable: true,
      value: small.reduce((sum, node) => sum + weightOf(node), 0),
      writable: true,
    })
  }
  kept.push(bucket)
  return kept
}

/** The `sumKeys` totals of the absorbed items, so the bucket carries them too. */
function sumValues(nodes: LayoutNode[]) {
  const totals: Record<string, number> = {}
  for (const node of nodes) {
    for (const [key, value] of Object.entries(node.vs || {})) {
      totals[key] = (totals[key] || 0) + (value as number)
    }
  }
  return Object.keys(totals).length ? totals : undefined
}

const VALUE_SCALES: Record<string, (value: number) => number> = {
  log: (value) => Math.log1p(Math.max(value, 0)),
  sqrt: (value) => Math.sqrt(Math.max(value, 0)),
}

/** Draw order: a set of siblings, then the descendants of each in turn. */
export function flattenNodes(nodes: LayoutNode[]): LayoutNode[] {
  const flat = nodes.slice()
  for (const node of nodes) {
    if (node._children?.length) {
      flat.push(...flattenNodes(node._children))
    }
  }
  return flat
}

/**
 * Pass two: the geometry.
 *
 * Packs each set of siblings into its parent's rectangle, writing the
 * coordinates onto the nodes the first pass produced.
 */
function layoutLevel(
  nodes: LayoutNode[],
  rect: any,
  layout: LayoutOptions,
  weighted: boolean,
  parentSum?: number
) {
  if (parentSum !== undefined) {
    for (const node of nodes) {
      node.gs = parentSum
    }
  }
  packInto(nodes, rect, weighted)

  for (const node of nodes) {
    if (node._children?.length) {
      layoutLevel(node._children, getSubRect(node, rect, layout), layout, weighted, node.s)
    }
  }
}

/** Writes the geometry for a whole tree of nodes, then applies headerBoxes. */
export function layoutNodes(nodes: LayoutNode[], rect: any, layout: LayoutOptions) {
  layoutLevel(nodes, rect, layout, isWeighted(layout))
  applyHeaderBoxes(flattenNodes(nodes), layout)
}

/** Linear is the default and needs no weights, so it keeps v4's arithmetic. */
function isWeighted(layout: LayoutOptions) {
  const scale = layout.valueScale
  return scale !== 'linear' && scale !== undefined
}

function scaleFor(layout: LayoutOptions) {
  const scale = layout.valueScale
  if (typeof scale === 'function') {
    return scale
  }
  return VALUE_SCALES[scale as string] || ((value: number) => value)
}

/** The rectangle left for a group's children once its border and caption are taken. */
function getSubRect(sq: any, rect: any, layout: LayoutOptions) {
  const { borderWidth, captions, displayMode } = layout
  const sp = displayMode === 'headerBoxes' ? 0 : layout.spacing
  const bw =
    displayMode === 'headerBoxes'
      ? { b: 0, l: 0, r: 0, t: 0 }
      : parseBorderWidth(borderWidth, sq.w / 2, sq.h / 2)
  const subRect = {
    ...rect,
    h: sq.h - 2 * sp - bw.t - bw.b,
    w: sq.w - 2 * sp - bw.l - bw.r,
    x: sq.x + sp + bw.l,
    y: sq.y + sp + bw.t,
  }
  if (shouldDrawCaption(displayMode, subRect, captions)) {
    const captionHeight = getCaptionHeight(
      displayMode,
      subRect,
      toFont(captions.font),
      valueOrDefault(captions.padding, 3)
    )
    subRect.y += captionHeight
    subRect.h -= captionHeight
  }
  return subRect
}

/**
 * The hierarchy pass on its own: the nested nodes, in draw order, with no
 * geometry. Takes no rectangle, which is the whole point - the controller needs
 * the node count before the chart area is known.
 */
export function buildNodes(tree: any, keys: string[], layout: LayoutOptions): LayoutNode[] {
  const { groups, leafKey, unsorted } = layout
  const input = isObject(tree) ? normalizeTreeToArray(keys, leafKey, tree) : tree

  const weighted = isWeighted(layout)
  let nodes: LayoutNode[]
  if (groups.length) {
    nodes = buildHierarchy(input, 0, keys, layout, weighted)
  } else {
    nodes = toNodes(input || [], keys) as LayoutNode[]
    if (weighted) {
      applyValueScale(nodes, scaleFor(layout))
    }
    if (layout.others) {
      nodes = applyOthers(nodes, layout.others, weighted)
    }
    if (!unsorted) {
      sortNodes(nodes, weighted)
    }
  }
  return nodes
}

/**
 * In headerBoxes mode a group is drawn as a header strip rather than a box
 * around its children, and a group whose caption does not fit is not drawn at
 * all. It is marked hidden rather than removed: the number of parsed nodes must
 * not depend on the size of the chart area.
 */
function applyHeaderBoxes(nodes: LayoutNode[], layout: LayoutOptions) {
  const { captions, displayMode } = layout
  if (displayMode !== 'headerBoxes') {
    return
  }
  const font = toFont(captions.font)
  const padding = valueOrDefault(captions.padding, 3)
  for (const node of nodes) {
    if (node.isLeaf) {
      continue
    }
    if (shouldDrawCaption(displayMode, node, captions)) {
      node.h = getCaptionHeight(displayMode, node, font, padding)
      node.hidden = false
    } else {
      node.hidden = true
    }
  }
}

/** Turns the user's input into the flat list of rectangles the chart draws. */
export function buildData(
  tree: any,
  keys: string[],
  mainRect: DrawRect,
  layout: LayoutOptions
): TreemapDataPoint[] {
  const nodes = buildNodes(tree, keys, layout)
  layoutNodes(nodes, mainRect, layout)
  return flattenNodes(nodes)
}
